query Query(
  $whereI: InventoryWhereInput, 
  $whereD: InventoryCountDetailWhereInput,
  $whereC: InventoryCountWhereInput
) {
  inv:inventory(where: $whereI, first: 1) {
    edges {
      node {
        id
        number
        active
        barcode
        quantity {
          value
          unitId
        }
        inventoryStatusId
        inventoryTypeId
        locationId
        lotId
        masterInventoryId
        externalId
        productStrategyProcessId
        productStrategyProcess {
          id
          productStrategy {
            product { id externalId name }
          }
        }
        destinationTransactions(
          where: {
            destinationInventoryStatusId: {
              _eq: "Count"
            }
          },
          first:1,
          orderBy: {field:createdAt, direction:desc}
        ){
          edges {
            node {
              sourceInventoryStatusId
            }
          }
        }
      }
    }
  }
  detail:inventoryCountDetail(where:$whereD) {
    edges {
      node {
        id
        ejected
        approved
        complete
        expectedLocationId
        expectedQuantity {value unitId}
      }
    }
  }
  inventoryCount(where:$whereC){
    edges{
      node {
        id
        progress
      }
    }
  }
}

query Query($where: MasterInventoryWhereInput, $orderBy: [MasterInventoryOrderByInput!], $first: Int, $after: String) {
  m:masterInventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        number
        inventory {
          total
    }
  }
  }
  }
}

